// ESM COLD-RESOLUTION arm B (issue #134): the same shape with a NON-mediated specifier.
//
// `node:path` is not a capability surface, so capwall's `resolve`/`load` hooks see it, decline to
// mediate it, and hand it back to Node untouched. Everything else about this import is identical
// to `esm-cold-mediated.mjs`: same directory, same package, same fresh-query cache key, same one
// builtin dependency. So the paired delta isolates the mediated half — the synthetic module
// source generation and `getEsmShim` — from the loader-thread round trip that BOTH arms pay and
// that belongs to Node, not to capwall.
import * as nodePath from "node:path";

export const boundJoin = nodePath.join;
export const kind = typeof nodePath.join;
